function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}
tw.local.sql =
	"INSERT INTO " +
	tw.env.LKP_DB_Schema +
	".ODC_RequestInfo" +
	"(liqAmount, liqCurrency, isLiquidated ,requestNo, requestNature , requestType, requestDate, requestState,requestStatus, parentRequestNo, REVERSALREASON,CLOSUREREASON,SUBSTATUS,BPMINSTANCENUMBER," +
	"LIQDEBITVALUEDATE, LIQCREDITVALUEDATE, LIQDEBITACCNUM, LIQCREDITACCOUNTCLASS, LIQCREDITBRANCHCODE, LIQCREDITBALANCESIGN, LIQCREDITACCOUNTCURRENCY, LIQCREDITACCOUNTBALANCE, STANDARDEXRATE, NEGOTIATEDEXRATE,LIQCREDITAMOUNTINACCOUNT, OUTSTANDINGAMOUNT,BRANCHNAME,INITIATOR," +
	" fcContractNo ,contractStage , exportPurpose ,paymentTerms ,productCategory, commodityDescription,cif, customerName, " +
	// + " collectionCurrency, standardExRate, negotiatedExRate,"
	" MAXIMUMCOLLECTIONDATE, REQUESTCURRENCY, DOCUMENTAMOUNT, ADVANCEAMOUNT, COLLECTIONACCOUNT, CHARGESACCOUNT, currentStepName, FOLDERPATH " +
	")" +
	" VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";

tw.local.sqlParameters = new tw.object.listOf.SQLParameter();

tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.liqAmount));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.liqCurrency));

var liquidated = "0";
if (tw.local.odcRequest.isLiquidated) liquidated = "1";

