tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.appInfo.stepName));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.folderPath));

// add function to add 1hour to the input date
function addOneHourToDate(date) {
	if (date == null) return null;
	var newDate = new Date(date);
	newDate.setHours(newDate.getHours() + 1);
	return newDate;
}
