"]},"name":"Update Odc Collection Data","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"2cd89407-e68c-4975-86f1-7f995694896d","scriptFormat":"text/x-javascript","script":{"content":["/**-------------------------- Add SQL Parameters --------------------------**/
function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}
tw.local.sql =
	"UPDATE " +
	tw.env.LKP_DB_Schema +
	".ODC_RequestInfo SET " +
	"(liqAmount, liqCurrency, isLiquidated , requestNature , requestType, requestDate, requestState,requestStatus, parentRequestNo, REVERSALREASON,CLOSUREREASON,SUBSTATUS,BPMINSTANCENUMBER," +
	"LIQDEBITVALUEDATE, LIQCREDITVALUEDATE, LIQDEBITACCNUM, LIQCREDITACCOUNTCLASS, LIQCREDITBRANCHCODE, LIQCREDITBALANCESIGN, LIQCREDITACCOUNTCURRENCY, LIQCREDITACCOUNTBALANCE, STANDARDEXRATE, NEGOTIATEDEXRATE,LIQCREDITAMOUNTINACCOUNT, OUTSTANDINGAMOUNT, currentStepName, FOLDERPATH" +
	" ) " +
	" =(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)" +
	" WHERE requestNo = ? ";

tw.local.sqlParameters = new tw.object.listOf.SQLParameter();

tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.liqAmount));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.liqCurrency));

var liquidated = "0";
if (tw.local.odcRequest.isLiquidated) liquidated = "1";

tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(liquidated));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.requestNature.name));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.requestType.name));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(addOneHourToDate(tw.local.odcRequest.requestDate)));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.BasicDetails.requestState));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.appInfo.status));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.parentRequestNo));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.reversalReason));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.closureReason));

tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.appInfo.subStatus));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.system.currentProcessInstanceID));

tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(addOneHourToDate(tw.local.odcRequest.ContractLiquidation.debitValueDate)));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(addOneHourToDate(tw.local.odcRequest.ContractLiquidation.creditValueDate)));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.debitedAccountNo));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.creditedAccount.accountClass.value));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.creditedAccount.branchCode));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.creditedAccount.balanceSign));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.creditedAccount.currency.name));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.creditedAccount.balance));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.creditedAmount.standardExRate));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.creditedAmount.negotiatedExRate));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.ContractLiquidation.creditedAmount.amountInAccount));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.FinancialDetailsFO.outstandingAmount));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.appInfo.stepName));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.folderPath));

tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.requestNo));

// add function to add 1hour to the input date
function addOneHourToDate(date) {
	if (date == null) return null;
	var newDate = new Date(date);
	newDate.setHours(newDate.getHours() + 1);
	return newDate;
}
